    font-size: 40px;
    line-height: 1.4;
  }

  .pf-chapter,
  .pf-hero {
    padding: 0 20px;
    height: auto;
    min-height: 100dvh;
    padding-top: 64px;
    padding-bottom: 64px;
  }
}
