<boltAction type="file" filePath="src/App.tsx" contentType="text/typescript">import { useEffect, useRef, useState, type ReactNode } from 'react';
import { ImageIcon, Mail, ArrowDown } from 'lucide-react';
import './portfolio.css';

type Work = {
  title: string;
  role: string;
  desc: string;
};

const works: Work[] = [
  {
    title: '모바일 은행 앱 리디자인',
    role: '프로덕트 디자이너 · 2024',
    desc: '복잡했던 이체 흐름을 3단계로 줄이고, 전체 화면 체계를 새로 잡았어요. 출시 후 이체 완료율이 눈에 띄게 늘었어요.',
  },
  {
    title: '동네 책방 예약 서비스',
    role: '프로덕트 디자이너 · 2023',
    desc: '작은 책방 사장님들이 직접 모임 자리를 관리할 수 있도록 처음부터 끝까지 설계했어요. 지금도 여러 책방에서 쓰고 있어요.',
  },
  {
    title: '사내 협업 도구 디자인 시스템',
    role: '디자인 시스템 리드 · 2022',
    desc: '흩어져 있던 컴포넌트를 하나의 체계로 정리해서, 새 화면 하나 만드는 시간을 절반으로 줄였어요.',
  },
];

function useReveal<T extends HTMLElement>() {
  const ref = useRef<T | null>(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const node = ref.current;
    if (!node) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.25 },
    );

    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  return { ref, visible };
}

function Reveal({ children }: { children: ReactNode }) {
  const { ref, visible } = useReveal<HTMLDivElement>();

  return (
    <div ref={ref} className={visible ? 'pf-reveal is-visible' : 'pf-reveal'}>
      {children}
    </div>
  );
}

