  --bg: oklch(0.985 0.002 var(--hue));
  --surface: oklch(1 0 0);
  --surface-2: oklch(0.995 0.001 var(--hue));
  --border: oklch(0.92 0.006 var(--hue));
  --border-strong: oklch(0.88 0.008 var(--hue));
  --muted: oklch(0.55 0.01 var(--hue));
  --text: oklch(0.2 0.008 var(--hue));
