  font-size: 13.5px; color: var(--muted); cursor: pointer; user-select: none;
}
.cr-nav-item:hover { color: var(--text); }
.cr-nav-item.active {
  background: color-mix(in oklch, var(--border) 55%, transparent);
  color: var(--text); font-weight: 500;
}

