/* 소개·홍보형 챕터 전용 보완 스타일 — kit 클래스를 재정의하지 않고 별도 클래스만 씀 */

.pf-serif {
  font-family: 'Noto Serif KR', serif;
}

.pf-chapter {
  height: 100dvh;
  display: flex;
  align-items: center;
  padding: 0 32px;
}

.pf-hero {
  height: 100dvh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 0 32px;
}

.pf-hero-title {
  font-size: 56px;
  line-height: 1.3;
  margin: 0;
  letter-spacing: -0.02em;
}

.pf-chapter-title {
  font-size: 56px;
  line-height: 1.35;
  margin: 0;
  letter-spacing: -0.02em;
}

/* 좌우 2단 — 모바일에서는 1단으로 접힘 */
.pf-split {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 48px;
  align-items: center;
  width: 100%;
}

.pf-media {
  width: 100%;
  min-height: 200px;
  max-height: 200px;
  background: var(--accent-soft);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.pf-media-hero {
  width: 100%;
  aspect-ratio: 16 / 9;
  max-height: 200px;
  background: var(--accent-soft);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.pf-reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 600ms ease-out, transform 600ms ease-out;
}

.pf-reveal.is-visible {
  opacity: 1;
  transform: translateY(0);
}

@media (prefers-reduced-motion: reduce) {
  .pf-reveal {
    opacity: 1;
    transform: none;
  }
}

@media (max-width: 1023px) {
  .pf-split {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .pf-split .pf-text-first {
    order: 1;
  }

  .pf-split .pf-media-second {
    order: 2;
  }

  .pf-hero-title,
  .pf-chapter-title {
    font-size: 40px;
    line-height: 1.4;
  }

  .pf-chapter,
  .pf-hero {
    padding: 0 20px;
    height: auto;
    min-height: 100dvh;
    padding-top: 64px;
    padding-bottom: 64px;
  }
}
